CREATE TABLE agent_catalog (id TEXT PRIMARY KEY,company_id TEXT NOT NULL,name TEXT NOT NULL,purpose TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','approved','rejected','retired')),created_by TEXT NOT NULL,reviewed_by TEXT,version BIGINT NOT NULL DEFAULT 1,created_at BIGINT NOT NULL,updated_at BIGINT NOT NULL);
CREATE TABLE agent_versions (id TEXT PRIMARY KEY,agent_id TEXT NOT NULL REFERENCES agent_catalog(id),version_number BIGINT NOT NULL,prompt TEXT NOT NULL,allowed_sources_json TEXT NOT NULL,prohibited_actions_json TEXT NOT NULL DEFAULT '["approve","sign","pay"]',status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','approved','rejected','retired')),created_by TEXT NOT NULL,reviewed_by TEXT,version BIGINT NOT NULL DEFAULT 1,created_at BIGINT NOT NULL,updated_at BIGINT NOT NULL,UNIQUE(agent_id,version_number));
CREATE TABLE agent_pools (id TEXT PRIMARY KEY,company_id TEXT NOT NULL,name TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','retired')),created_by TEXT NOT NULL,version BIGINT NOT NULL DEFAULT 1,created_at BIGINT NOT NULL,updated_at BIGINT NOT NULL,UNIQUE(company_id,name));
CREATE TABLE agent_pool_members (id TEXT PRIMARY KEY,pool_id TEXT NOT NULL REFERENCES agent_pools(id),user_id TEXT NOT NULL,created_by TEXT NOT NULL,created_at BIGINT NOT NULL,UNIQUE(pool_id,user_id));
CREATE TABLE agent_assignments (id TEXT PRIMARY KEY,company_id TEXT NOT NULL,agent_version_id TEXT NOT NULL REFERENCES agent_versions(id),pool_id TEXT REFERENCES agent_pools(id),user_id TEXT,scope_path TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','revoked')),created_by TEXT NOT NULL,revoked_by TEXT,version BIGINT NOT NULL DEFAULT 1,created_at BIGINT NOT NULL,updated_at BIGINT NOT NULL,CHECK((pool_id IS NULL)<>(user_id IS NULL)));
CREATE TABLE ai_private_sessions (id TEXT PRIMARY KEY,company_id TEXT NOT NULL,user_id TEXT NOT NULL,assignment_id TEXT NOT NULL,scope_key TEXT NOT NULL,conversation_key TEXT NOT NULL,agent_assignment_id TEXT REFERENCES agent_assignments(id),created_at BIGINT NOT NULL,last_used_at BIGINT NOT NULL,UNIQUE(company_id,user_id,assignment_id,scope_key,conversation_key));
CREATE TABLE ai_invocation_evidence (id TEXT PRIMARY KEY,session_id TEXT NOT NULL REFERENCES ai_private_sessions(id),turn_id TEXT NOT NULL UNIQUE,company_id TEXT NOT NULL,user_id TEXT NOT NULL,agent_version_id TEXT REFERENCES agent_versions(id),question_digest TEXT NOT NULL,sources_digest TEXT NOT NULL,authority_snapshot_json TEXT NOT NULL,provider_snapshot_json TEXT NOT NULL,outcome TEXT NOT NULL CHECK(outcome IN ('succeeded','failed')),input_tokens BIGINT,output_tokens BIGINT,error TEXT,created_at BIGINT NOT NULL);
CREATE FUNCTION agent_guard() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF TG_TABLE_NAME IN ('ai_invocation_evidence','ai_private_sessions','agent_pool_members') OR TG_OP='DELETE' THEN RAISE EXCEPTION 'AGENT_EVIDENCE_IMMUTABLE' USING ERRCODE='23514'; END IF;
 IF TG_TABLE_NAME='agent_catalog' THEN IF (NEW.id,NEW.company_id,NEW.created_by,NEW.created_at) IS DISTINCT FROM (OLD.id,OLD.company_id,OLD.created_by,OLD.created_at) THEN RAISE EXCEPTION 'AGENT_SOURCE_IMMUTABLE' USING ERRCODE='23514'; END IF;
 ELSIF TG_TABLE_NAME='agent_versions' THEN IF (NEW.id,NEW.agent_id,NEW.version_number,NEW.prompt,NEW.allowed_sources_json,NEW.prohibited_actions_json,NEW.created_by,NEW.created_at) IS DISTINCT FROM (OLD.id,OLD.agent_id,OLD.version_number,OLD.prompt,OLD.allowed_sources_json,OLD.prohibited_actions_json,OLD.created_by,OLD.created_at) THEN RAISE EXCEPTION 'AGENT_VERSION_IMMUTABLE' USING ERRCODE='23514'; END IF;
 ELSIF TG_TABLE_NAME='agent_assignments' THEN IF (NEW.id,NEW.company_id,NEW.agent_version_id,NEW.pool_id,NEW.user_id,NEW.scope_path,NEW.created_by,NEW.created_at) IS DISTINCT FROM (OLD.id,OLD.company_id,OLD.agent_version_id,OLD.pool_id,OLD.user_id,OLD.scope_path,OLD.created_by,OLD.created_at) THEN RAISE EXCEPTION 'AGENT_ASSIGNMENT_IMMUTABLE' USING ERRCODE='23514'; END IF; END IF; RETURN NEW;
END $$;
DO $$ DECLARE t TEXT; BEGIN FOREACH t IN ARRAY ARRAY['agent_catalog','agent_versions','agent_pools','agent_pool_members','agent_assignments','ai_private_sessions','ai_invocation_evidence'] LOOP EXECUTE format('CREATE TRIGGER agent_guard BEFORE UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION agent_guard()',t);END LOOP;END $$;
DO $$ DECLARE t TEXT; BEGIN FOREACH t IN ARRAY ARRAY['agent_catalog','agent_versions','agent_pools','agent_assignments','ai_private_sessions','ai_invocation_evidence'] LOOP INSERT INTO work_cache_revisions(table_name) VALUES(t) ON CONFLICT DO NOTHING;EXECUTE format('CREATE TRIGGER work_cache_change AFTER INSERT OR UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION work_cache_changed()',t);EXECUTE format('CREATE TRIGGER work_cache_truncate AFTER TRUNCATE ON %I FOR EACH STATEMENT EXECUTE FUNCTION work_cache_changed()',t);END LOOP;END $$;
